mapper.select:
SELECT id, origin_name, store_name, file_path, ext, file_size,
       content_type, uploader_id, create_time, status, download_count
FROM file_info
WHERE id = #{id}
  AND uploader_id = #{uploaderId}

SELECT id, origin_name, store_name, file_path, ext, file_size, content_type, uploader_id, create_time, status, download_count FROM file_info WHERE uploader_id = #{uploaderId}
AND ext IN #{e}
AND origin_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY create_time DESC, id DESC

SELECT COALESCE(SUM(download_count), 0)
FROM file_info
WHERE uploader_id = #{uploaderId}

mapper.update:
UPDATE file_info
SET status = #{status}
WHERE id = #{id}
  AND uploader_id = #{uploaderId}

UPDATE file_info
SET download_count = download_count + 1
WHERE id = #{id}
